559	// searchVerifyWalk consults every derivation at dir and then at each ancestor up to and including
560	// the root (""), and returns the first command any of them licenses.
561	func searchVerifyWalk(
562		dir string,
563		subject searchVerifySubject,
564		evidence *searchVerifyEvidence,
565		derivations []func(string, searchVerifySubject, *searchVerifyEvidence) *SearchVerifyCommand,
