706	func deriveSearchVerifySuiteGradle(dir string, subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
707		if !searchVerifySuiteApplies(subject, "Gradle") {
708			return nil
709		}
710		manifest := ""
711		for _, name := range []string{"build.gradle", "build.gradle.kts"} {
712			if evidence.exists(searchVerifyJoin(dir, name)) {
713				manifest = searchVerifyJoin(dir, name)
714				break
715			}
716		}
717		if manifest == "" {
718			return nil
719		}
720		wrapperDir, wrapperPath, ok := searchVerifyAncestorFile(dir, "gradlew", evidence)
721		if !ok {
722			return nil
723		}
724		if wrapperDir == dir {
725			return searchVerifySuiteCommand(wrapperDir, "./gradlew test", manifest+" + "+wrapperPath)
726		}
727		// The wrapper lives above the build this derivation is about. Running `./gradlew test` from the
728		// wrapper's own directory would test whatever build sits THERE, because Gradle does not discover
729		// a descendant build by walking down — but WHICH command names this one is decided by the
730		// settings script, not by the directory layout.
731		//
732		// Gradle locates the settings file by walking UP from its start directory and then keeps what it
733		// found only if that file declares a project AT the start directory; otherwise it discards the
734		// settings and runs the start directory as its own empty-settings build. So `-p <dir> test` is
735		// NOT "the root build with a different default project": in an ordinary multi-project layout it
736		// is the root build when the root settings declares <dir>, and a different, sibling-less build
737		// when it does not — where `project(":core")` dependencies no longer resolve. A `build.gradle`
738		// sitting in a subdirectory says nothing about which of the two it is.
739		relative, inside := searchVerifyRelative(wrapperDir, dir)
740		if !inside {
741			return nil
742		}
743		if settingsPath, _, own := searchVerifyGradleSettings(dir, evidence); own {
744			// The directory carries its own settings script, so it IS a build root and that is the
745			// settings file Gradle finds first when started there. `-p` is the spelling for that.
746			return searchVerifySuiteCommand(
747				wrapperDir,
748				"./gradlew -p "+shellQuotePath(relative)+" test",
749				manifest+" + "+wrapperPath+" + "+settingsPath,
750			)
751		}
752		settingsPath, settings, found := searchVerifyGradleSettings(wrapperDir, evidence)
753		project := ":" + strings.ReplaceAll(relative, "/", ":")
754		if !found || !searchVerifyGradleSettingsIncludes(settings, project) {
755			// Nothing in the tree says this directory is a build Gradle can be pointed at, so there is
756			// no command to emit. Silence costs a lookup; a `-p` that quietly ran a different build
757			// would report a pass the edit never earned.
758			return nil
759		}
760		if searchVerifyGradleSettingsRemapsProject(settings, project) {
761			// The project path is declared, but the settings script moves it somewhere else on disk, so
762			// the path derived from THIS directory names a different tree. `./gradlew :lib:test` would
763			// run, and pass, about code the edit never touched — which is worse than emitting nothing.
764			return nil
765		}
766		// An included subproject is addressed by its project path from the root of the build that
767		// declares it — the documented spelling, `gradle :subproject:taskName`.
768		return searchVerifySuiteCommand(
769			wrapperDir,
770			"./gradlew "+shellQuote(project+":test"),
771			manifest+" + "+wrapperPath+" + "+settingsPath,
772		)
773	}
