775	// searchVerifyGradleSettings returns the settings script that makes a directory a Gradle build root,
776	// with its content, or false when the directory is not one.
777	func searchVerifyGradleSettings(dir string, evidence *searchVerifyEvidence) (string, string, bool) {
778		for _, name := range []string{"settings.gradle", "settings.gradle.kts"} {
779			candidate := searchVerifyJoin(dir, name)
780			if content, ok := evidence.file(candidate); ok {
781				return candidate, content, true
782			}
783		}
784		return "", "", false
785	}
786	
787	// searchVerifyGradleSettingsIncludes reports whether a settings script declares the project path.
788	//
789	// It reads only LITERAL `include` arguments, in either DSL — `include ':a:b'`, `include(":a:b")`,
790	// and the comma-separated and multi-line spellings of both. `includeBuild` composes a separate build
791	// rather than declaring a project, and `includeFlat` names a sibling directory rather than a project
792	// path, so neither answers this question; both are skipped along with any other identifier that
793	// merely starts with `include`. A settings script that COMPUTES its includes reports false, and the
794	// caller then emits nothing: this predicate exists to replace a guess, not to make a better one.
795	func searchVerifyGradleSettingsIncludes(settings, project string) bool {
796		want := strings.TrimPrefix(project, ":")
797		if want == "" {
798			return false
799		}
800		for _, argument := range searchVerifyGradleIncludeArguments(settings) {
801			if strings.TrimPrefix(argument, ":") == want {
802				return true
803			}
804		}
805		return false
806	}
807	
808	// searchVerifyGradleSettingsRemapsProject reports whether the settings script MOVES the project's
809	// directory, with `project(':lib').projectDir = file('other')` or the block spelling of the same
810	// assignment.
811	//
812	// A project path is derived here from a directory, and `include ':lib'` alone says that derivation
813	// holds. A remap breaks it: `:lib` is then a different tree, and `./gradlew :lib:test` for an edit
814	// in `lib/` runs, and passes, about code the edit never touched. That is worse than a command that
815	// cannot run, because nothing announces it.
816	//
817	// The scan is bounded to the STATEMENT the matching `project(...)` call starts — extended to the
818	// matching brace when one follows — so a `projectDir` assignment elsewhere in the script, about a
819	// different project, is not read as this one's.
820	func searchVerifyGradleSettingsRemapsProject(settings, project string) bool {
821		want := strings.TrimPrefix(project, ":")
822		if want == "" {
823			return false
824		}
825		script := searchVerifyStripScriptComments(settings)
826		for index := 0; index < len(script); {
827			character := script[index]
828			if character == '\'' || character == '"' {
829				_, width := searchVerifyScriptStringLiteral(script[index:])
830				if width == 0 {
831					index++
832					continue
833				}
834				index += width
835				continue
836			}
837			if !searchVerifyScriptIdentifierByte(character) {
838				index++
839				continue
840			}
841			start := index
842			for index < len(script) && searchVerifyScriptIdentifierByte(script[index]) {
843				index++
844			}
845			if script[start:index] != "project" {
846				continue
847			}
848			arguments, width := searchVerifyGradleCallArguments(script[index:])
849			if width == 0 {
850				continue
851			}
852			named := false
853			for _, argument := range arguments {
854				if strings.TrimPrefix(argument, ":") == want {
855					named = true
856					break
857				}
858			}
859			index += width
860			if named && searchVerifyGradleAssignsProjectDir(searchVerifyGradleStatementTail(script[index:])) {
861				return true
862			}
863		}
864		return false
865	}
866	
867	// searchVerifyGradleAssignsProjectDir reports whether a statement MOVES a project's directory rather
868	// than merely naming it.
869	//
870	// `println(project(':lib').projectDir)` reads the property; the project is still where it was, and
871	// declining on a read costs a command that would have run for no reason. Only an assignment to it,
872	// or the setter the assignment is sugar for, relocates the project. `==` is a comparison, not an
873	// assignment, and is read as a mention.
874	func searchVerifyGradleAssignsProjectDir(statement string) bool {
875		if strings.Contains(statement, "setProjectDir") {
876			return true
877		}
878		const property = "projectDir"
879		for index := 0; index < len(statement); {
880			found := strings.Index(statement[index:], property)
881			if found < 0 {
882				return false
883			}
884			index += found + len(property)
885			after := strings.TrimLeft(statement[index:], " \t\r\n")
886			if strings.HasPrefix(after, "=") && !strings.HasPrefix(after, "==") {
887				return true
888			}
889		}
890		return false
891	}
892	
893	// searchVerifyGradleStatementTail returns what remains of the statement that has just been read up
894	// to its call: the rest of the line, extended while the line is continued, or the matching brace
895	// when the call is followed by a block.
896	//
897	// STRING LITERALS are stepped over whole in both, for the same reason the include walk does it: a
898	// `}` or a `;` inside one is text, and ending the window at it would stop the scan before the
899	// `projectDir` assignment that follows — the caller would then emit `./gradlew :lib:test` for a
900	// project the settings script moved, which runs and passes about a different directory.
901	func searchVerifyGradleStatementTail(rest string) string {
902		index := 0
903		for index < len(rest) && (rest[index] == ' ' || rest[index] == '\t') {
904			index++
905		}
906		if index < len(rest) && rest[index] == '{' {
907			depth := 0
908			for scan := index; scan < len(rest); {
909				switch rest[scan] {
910				case '\'', '"':
911					if width := searchVerifyGradleLiteralWidth(rest[scan:]); width > 0 {
912						scan += width
913						continue
914					}
915				case '{':
916					depth++
917				case '}':
918					depth--
919					if depth == 0 {
920						return rest[:scan+1]
921					}
922				}
923				scan++
924			}
925			return rest
926		}
927		for scan := index; scan < len(rest); {
928			switch rest[scan] {
929			case '\'', '"':
930				if width := searchVerifyGradleLiteralWidth(rest[scan:]); width > 0 {
931					scan += width
932					continue
933				}
934			case ';':
935				return rest[:scan]
936			case '\n':
937				if !searchVerifyGradleStatementContinues(rest[:scan], rest[scan+1:]) {
938					return rest[:scan]
939				}
940			}
941			scan++
942		}
943		return rest
944	}
945	
946	// searchVerifyGradleLiteralWidth reports how far one string literal reaches, or zero when the quote
947	// is not closed — in which case the caller steps a single byte rather than swallowing the rest.
948	func searchVerifyGradleLiteralWidth(rest string) int {
949		_, width := searchVerifyScriptStringLiteral(rest)
950		return width
951	}
952	
953	// searchVerifyGradleStatementContinues reports whether a statement carries on past a newline: the
954	// line ends on an operator or separator, or the next one opens with the `.` of a chained call, which
955	// is how Kotlin spells a continued member access.
956	func searchVerifyGradleStatementContinues(before, after string) bool {
957		trimmed := strings.TrimRight(before, " \t\r")
958		for _, suffix := range []string{",", "\\", ".", "=", "("} {
959			if strings.HasSuffix(trimmed, suffix) {
960				return true
961			}
962		}
963		next := strings.TrimLeft(after, " \t\r\n")
964		return strings.HasPrefix(next, ".")
965	}
966	
967	// searchVerifyGradleIncludeArguments returns every string literal passed to an `include` call.
968	//
969	// It walks the script token by token rather than searching for the word, because `include` is
970	// ordinary text as well as a call: `println("include ':modules:core'")` contains it, and reading
971	// that as a declaration names a project the settings file never declares — the emitted
972	// `./gradlew :modules:core:test` then cannot run. Comments are removed first and STRING LITERALS
973	// are stepped over whole — including Groovy/Kotlin triple-quoted blocks, which span newlines — so
974	// only an `include` in code position starts a call.
975	func searchVerifyGradleIncludeArguments(script string) []string {
976		script = searchVerifyStripScriptComments(script)
977		var arguments []string
978		for index := 0; index < len(script); {
979			character := script[index]
980			if character == '\'' || character == '"' {
981				_, width := searchVerifyScriptStringLiteral(script[index:])
982				if width == 0 {
983					// An unterminated quote: step past it rather than swallowing the rest of the file.
984					index++
985					continue
986				}
987				index += width
988				continue
989			}
990			if !searchVerifyScriptIdentifierByte(character) {
991				index++
992				continue
993			}
994			start := index
995			for index < len(script) && searchVerifyScriptIdentifierByte(script[index]) {
996				index++
997			}
998			// Whole-identifier equality subsumes the old neighbour checks: `includeBuild`, `includeFlat`
999			// and `myinclude` are different identifiers and answer a different question.
1000			if script[start:index] != "include" {
1001				continue
1002			}
1003			found, width := searchVerifyGradleCallArguments(script[index:])
1004			arguments = append(arguments, found...)
1005			index += width
1006		}
1007		return arguments
1008	}
1009	
1010	// searchVerifyGradleCallArguments collects the string literals of one call's argument list and
1011	// reports how far it consumed, or a zero width when what follows the identifier is not a call at
1012	// all. Groovy allows the parentheses to be dropped, so the list ends either at the matching `)` or
1013	// at the end of the STATEMENT — which is the end of the line, extended while the line is continued,
1014	// OR a `;` before it.
1015	//
1016	// A CALL SHAPE is required first, because `include` is a legal ordinary name as well as a settings
1017	// method: `val include = ":modules:core"` and `def include = ':modules:core'` both bind a variable,
1018	// and reading the literal on the right of the `=` as an argument named a project the settings script
1019	// never declares — `./gradlew :modules:core:test` then fails with "Project 'modules' not found in
1020	// root project". An argument list starts at `(` or, in the command-expression form, at the literal
1021	// itself; anything else after the identifier (`=`, `.`, `:`, a newline) is a different construct.
1022	//
1023	// The semicolon is not a detail. A line is not a statement in Groovy: `include ':app'; project(':app')
1024	// .projectDir = file('lib')` is the ordinary spelling for an include plus a directory remap, and
1025	// without the `;` terminator this scanner read `'lib'` — the argument of a DIFFERENT call, on the
1026	// other side of the separator — as a third included project and named `./gradlew :lib:test` for a
1027	// project the settings file never declares. The parenthesised form already stopped at its own `)`,
1028	// so the two spellings of the same include disagreed about everything that followed them on the
1029	// line; a terminator is what makes them agree.
1030	func searchVerifyGradleCallArguments(rest string) ([]string, int) {
1031		var arguments []string
1032		index := 0
1033		for index < len(rest) && (rest[index] == ' ' || rest[index] == '\t') {
1034			index++
1035		}
1036		if index >= len(rest) {
1037			return nil, 0
1038		}
1039		switch rest[index] {
1040		case '(', '\'', '"':
1041		default:
1042			return nil, 0
1043		}
1044		parenthesised := rest[index] == '('
1045		depth := 0
1046		// literal reports whether every argument seen so far IS a literal, rather than a subexpression
1047		// one happens to sit in. `include(if (flag) ":app" else ":other")` and its Groovy ternary name
1048		// ONE project, chosen at configuration time, and collecting both records one Gradle never
1049		// included — `./gradlew :other:test` then fails with "Project 'other' not found in root
1050		// project". Nothing in the text says which branch is taken, so an argument list that is not a
1051		// plain sequence of literals declares nothing here.
1052		literal := true
1053		for index < len(rest) {
1054			switch character := rest[index]; character {
1055			case '(':
1056				depth++
1057				index++
1058				if depth > 1 || !parenthesised {
1059					literal = false
1060				}
1061			case ')':
1062				depth--
1063				index++
1064				if parenthesised && depth == 0 {
1065					return searchVerifyGradleLiteralArguments(arguments, literal), index
1066				}
1067			case '\'', '"':
1068				content, width := searchVerifyScriptStringLiteral(rest[index:])
1069				if width == 0 {
1070					return searchVerifyGradleLiteralArguments(arguments, literal), index + 1
1071				}
1072				arguments = append(arguments, content)
1073				index += width
1074			case ';':
1075				// A command-expression argument list ends at the statement separator exactly as it ends
1076				// at the newline below. Inside parentheses a `;` is somebody else's syntax.
1077				if parenthesised || depth > 0 {
1078					index++
1079					continue
1080				}
1081				return searchVerifyGradleLiteralArguments(arguments, literal), index
1082			case '\n':
1083				if parenthesised || depth > 0 {
1084					index++
1085					continue
1086				}
1087				continued := strings.TrimRight(rest[:index], " \t\r")
1088				if strings.HasSuffix(continued, ",") || strings.HasSuffix(continued, "\\") {
1089					index++
1090					continue
1091				}
1092				return searchVerifyGradleLiteralArguments(arguments, literal), index
1093			default:
1094				if character != ' ' && character != '\t' && character != '\r' && character != ',' {
1095					literal = false
1096				}
1097				index++
1098			}
1099		}
1100		return searchVerifyGradleLiteralArguments(arguments, literal), index
1101	}
1102	
1103	// searchVerifyGradleLiteralArguments passes the collected arguments through only when the list was a
1104	// plain sequence of literals. Declining costs a lookup; a project path read out of a branch that was
1105	// not taken costs a hard-gate command that cannot run.
1106	func searchVerifyGradleLiteralArguments(arguments []string, literal bool) []string {
1107		if !literal {
1108			return nil
1109		}
1110		return arguments
1111	}
1112	
1113	// searchVerifyScriptStringLiteral reads one string literal, returning its content and its width, or
1114	// a zero width when it is not closed.
1115	//
1116	// TRIPLE-quoted blocks are read whole, across newlines, which the single-quote form cannot do. Both
1117	// DSLs spell a multi-line string that way, and an ordinary one-line literal terminates at the
1118	// newline, so a block like
1119	//
1120	//	val example = """
1121	//	    include(":lib")
1122	//	"""
1123	//
1124	// left its body in code position and `include(":lib")` was read as a declaration — `./gradlew
1125	// :lib:test` for a project the settings script never declares. Reading the block whole also makes
1126	// `include(""":lib""")` work, because the delimiter is stripped and the content is the argument.
