// searchVerifyStartDir is the directory a manifest walk for filePath begins in, "" for the root.
func searchVerifyStartDir(filePath string) string {
	dir := path.Dir(filePath)
	if dir == "." || dir == "/" {
		return ""
	}
	return dir
