593		deriveSearchVerifyGradle,
594		deriveSearchVerifyNode,
595		deriveSearchVerifyComposer,
596		deriveSearchVerifyPytest,
597		deriveSearchVerifyRuby,
598		deriveSearchVerifyCMake,
599		deriveSearchVerifyMake,
