626	// command was derivable) and the derivation (whole suite) so the reader knows it is unfiltered and slow.
627	func searchVerifySuiteCommand(dir, command, derived string) *SearchVerifyCommand {
628		return searchVerifySuiteCommandLiteral(searchVerifyRunIn(dir, command), derived)
