631	// searchVerifySuiteCommandLiteral is searchVerifySuiteCommand for a derivation that has already
632	// decided where the command runs. Maven's reactor is the case: a module is addressed from the
633	// repository root with `-pl`, so prefixing a `cd` into the module would be wrong rather than
634	// merely redundant.
635	func searchVerifySuiteCommandLiteral(command, derived string) *SearchVerifyCommand {
636		return &SearchVerifyCommand{
637			Command:     command,
638			Targets:     "whole test suite (no narrow test command derivable)",
639			DerivedFrom: derived + " (whole suite)",
640		}
