643	// searchVerifySuiteApplies keeps a neighboring ecosystem manifest from selecting an unrelated suite.
644	// A covering test can establish the ecosystem for native or generated sources.
645	func searchVerifySuiteApplies(subject searchVerifySubject, ecosystem string) bool {
646		extensions := map[string]string{
647			"Cargo": ".rs .c .cc .cpp .cxx .h .hh .hpp .hxx .m .mm", "Maven": ".java .kt .scala .groovy", "Gradle": ".java .kt .kts .scala .groovy",
648			"Node": ".js .jsx .mjs .cjs .ts .tsx .mts .cts .vue .svelte", "Composer": ".php", "Pytest": ".py .pyw",
649			"Ruby": ".rb .rake .gemspec", "CMake": ".c .cc .cpp .cxx .h .hh .hpp .hxx .m .mm",
650		}
651		manifests := map[string]string{"Cargo": "Cargo.toml Cargo.lock build.rs", "Maven": "pom.xml", "Gradle": "build.gradle build.gradle.kts settings.gradle settings.gradle.kts", "Node": "package.json package-lock.json yarn.lock pnpm-lock.yaml bun.lock bun.lockb", "Composer": "composer.json composer.lock phpunit.xml phpunit.xml.dist", "Pytest": "pytest.ini tox.ini setup.cfg pyproject.toml", "Ruby": "Gemfile Gemfile.lock .rspec Rakefile", "CMake": "CMakeLists.txt"}
652		for _, file := range []string{subject.sourcePath, subject.testPath} {
653			if file == "" {
654				continue
655			}
656			for _, ext := range strings.Fields(extensions[ecosystem]) {
657				if strings.EqualFold(path.Ext(file), ext) {
658					return true
659				}
660			}
661			for _, manifest := range strings.Fields(manifests[ecosystem]) {
662				if path.Base(file) == manifest {
663					return true
664				}
665			}
666		}
667		return false
668	}
